namespace Aurora {
public sealed class TweakVariant {
    public Tweak Definition;public string Pt,En;public readonly HashSet<string> LegacyIds=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public string Label{get{return L.T(Pt,En);}}public override string ToString(){return Label;}
}
public sealed class TweakPreference {
    public string Id,Category,Pt,En,DescriptionPt,DescriptionEn;public readonly List<TweakVariant> Variants=new List<TweakVariant>();
    public string Title{get{return L.T(Pt,En);}}public bool Multiple{get{return Variants.Count>1;}}
}
public static class SettingsVisibility {
    public static bool Hidden(string raw,string page){if(String.IsNullOrWhiteSpace(raw)||raw.Trim().Equals("show:home",StringComparison.OrdinalIgnoreCase))return false;string[] parts=raw.ToLowerInvariant().Split(new[]{':'},2);if(parts.Length!=2||(parts[0]!="hide"&&parts[0]!="showonly"))throw new ArgumentException("Unsupported Settings visibility policy");bool contains=parts[1].Split(';').Contains(page,StringComparer.OrdinalIgnoreCase);return parts[0]=="hide"?contains:!contains;}
    public static string SetHidden(string raw,string page,bool hidden){if(page!="home"&&page!="aicomponents")throw new ArgumentException("Unsupported Settings page");string mode="hide";var values=new HashSet<string>(StringComparer.OrdinalIgnoreCase);if(!String.IsNullOrWhiteSpace(raw)&&!raw.Trim().Equals("show:home",StringComparison.OrdinalIgnoreCase)){string[] parts=raw.ToLowerInvariant().Split(new[]{':'},2);if(parts.Length!=2||(parts[0]!="hide"&&parts[0]!="showonly"))throw new ArgumentException("Unsupported Settings visibility policy");mode=parts[0];foreach(string value in parts[1].Split(new[]{';'},StringSplitOptions.RemoveEmptyEntries))values.Add(value);}bool include=mode=="hide"?hidden:!hidden;if(include)values.Add(page);else values.Remove(page);if(values.Count==0){if(mode=="showonly")throw new InvalidOperationException(L.T("A política permite somente esta página. Revise a política antes de ocultá-la.","Policy allows only this page. Review the policy before hiding it."));return "";}return mode+":"+String.Join(";",values.OrderBy(x=>x,StringComparer.OrdinalIgnoreCase));}
}
public sealed partial class Journal {
    public void RegistryPageChange(string title,TweakSetting setting){lock(this){var previous=store.Read(setting.Hive,setting.Path,setting.Name);string value=SettingsVisibility.SetHidden(previous.Exists?Convert.ToString(previous.Value):"",setting.PolicyPage,Convert.ToBoolean(setting.Value));RegistryChange(title,setting.Hive,setting.Path,setting.Name,value,RegistryValueKind.String);}}
}
public static class TweakPreferences {
    static Tweak Copy(Tweak source,IEnumerable<TweakSetting> values,string id=null){var all=values.ToArray();if(all.Length==0)return null;var first=all[0];return new Tweak{Id=id??source.Id,Category=source.Category,Pt=source.Pt,En=source.En,DescriptionPt=source.DescriptionPt,DescriptionEn=source.DescriptionEn,MinBuild=source.MinBuild,MaxBuild=source.MaxBuild,Recommended=source.Recommended,Source=source.Source,Hive=first.Hive,Path=first.Path,Name=first.Name,Value=first.Value,Kind=first.Kind,Delete=first.Delete,DeleteTree=first.DeleteTree,PolicyPage=first.PolicyPage,Extra=all.Skip(1).ToArray()};}
    static TweakPreference Preference(Tweak definition){return new TweakPreference{Id=definition.Id,Category=definition.Category,Pt=definition.Pt,En=definition.En,DescriptionPt=definition.DescriptionPt,DescriptionEn=definition.DescriptionEn};}
    static TweakVariant Variant(Tweak value,string pt=null,string en=null){var item=new TweakVariant{Definition=value,Pt=pt??value.Pt,En=en??value.En};item.LegacyIds.Add(value.Id);return item;}
    static TweakSetting Page(string hive,string page,bool hidden){return new TweakSetting{Hive=hive,Path=@"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer",Name="SettingsPageVisibility",Value=hidden,Kind=RegistryValueKind.String,PolicyPage=page};}
    public static List<TweakPreference> All(){var raw=TweakCatalog.All().ToDictionary(x=>x.Id,StringComparer.OrdinalIgnoreCase);var used=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var result=new List<TweakPreference>();
        Action<string,string,string,string,string[],string[],string[]> group=(id,title,en,category,ids,labels,english)=>{var pref=new TweakPreference{Id=id,Pt=title,En=en,Category=category,DescriptionPt="Escolha uma alternativa. A seleção só é aplicada ao confirmar Aplicar selecionados; o estado anterior é salvo para restauração.",DescriptionEn="Choose an option. Changes run only after confirming Apply selected; previous state is backed up."};for(int i=0;i<ids.Length;i++){Tweak original;if(!raw.TryGetValue(ids[i],out original))continue;pref.Variants.Add(Variant(Copy(original,original.Settings()),labels[i],english[i]));used.Add(original.Id);}if(pref.Variants.Count>0)result.Add(pref);};
