        group("wallpaper-quality","Qualidade do papel de parede JPEG","JPEG wallpaper quality","visual",new[]{"dism-1-4-0","dism-1-4-1","dism-1-4-2"},new[]{"60%","Padrão do Windows","100%"},new[]{"60%","Windows default","100%"});
        string[] desktop={"Este Computador","Lixeira","Painel de Controle","Pasta do usuário","Rede","Bibliotecas"},desktopEn={"This PC","Recycle Bin","Control Panel","User folder","Network","Libraries"};for(int i=0;i<desktop.Length;i++)group("desktop-icon-"+i,desktop[i]+" na área de trabalho",desktopEn[i]+" on desktop","explorer",new[]{"dism-6-"+i+"-0","dism-6-"+i+"-1","dism-6-"+i+"-2"},new[]{"Padrão do Windows","Mostrar","Ocultar"},new[]{"Windows default","Show","Hide"});
        group("ime-mode","Modo do teclado IME","IME input mode","system",new[]{"dism-12-0-0","dism-12-0-1"},new[]{"Chinês","Alfanumérico"},new[]{"Chinese","Alphanumeric"});
        group("network-protocol","Preferência IPv4 / IPv6 (avançado)","IPv4 / IPv6 preference (advanced)","network",new[]{"ipv4-preferred","ipv6-off","teredo-off"},new[]{"Preferir IPv4","Desativar IPv6","Desativar somente Teredo"},new[]{"Prefer IPv4","Disable IPv6","Disable Teredo only"});
        var protocol=result.Last();var normal=Copy(raw["ipv4-preferred"],new[]{new TweakSetting{Hive="HKLM",Path=raw["ipv4-preferred"].Path,Name="DisabledComponents",Value=0}},"protocol-default");protocol.Variants.Insert(0,Variant(normal,"Ativar IPv4 e IPv6","Enable IPv4 and IPv6"));
