        var hidden=result.Last();hidden.Variants[0].Definition=Copy(raw["hidden-files"],raw["hidden-files"].Settings().Concat(new[]{new TweakSetting{Hive="HKCU",Path=raw["hidden-files"].Path,Name="ShowSuperHidden",Value=0}}));var hide=Copy(raw["hidden-files"],new[]{new TweakSetting{Hive="HKCU",Path=raw["hidden-files"].Path,Name="Hidden",Value=2},new TweakSetting{Hive="HKCU",Path=raw["hidden-files"].Path,Name="ShowSuperHidden",Value=0}},"hide-hidden-files");hidden.Variants.Insert(0,Variant(hide,"Ocultar","Hide"));
        Action<string,string[],string,string> merge=(main,ids,title,en)=>{var origin=raw[main];var pref=Preference(origin);if(title!=null){pref.Pt=title;pref.En=en;}var variant=Variant(Copy(origin,origin.Settings()));var settings=variant.Definition.Settings().ToList();used.Add(main);foreach(string id in ids){Tweak other;if(!raw.TryGetValue(id,out other))continue;used.Add(id);variant.LegacyIds.Add(id);foreach(var value in other.Settings())if(!settings.Any(x=>TweakRegistryEngine.Identity(x)==TweakRegistryEngine.Identity(value)))settings.Add(value);}variant.Definition=Copy(origin,settings);variant.Definition.Pt=pref.Pt;variant.Definition.En=pref.En;pref.Variants.Add(variant);result.Add(pref);};
        merge("game-recording",new[]{"dism-3-8-0"},null,null);merge("notification-center",new[]{"dism-0-3-0"},null,null);
        merge("app-suggestions",new[]{"dism-3-0-0","dism-3-1-0","dism-3-3-0","dism-3-5-0","dism-3-7-0"},"Reduzir sugestões e instalações promocionais","Reduce suggestions and promotional installs");
        merge("location-apps",new[]{"raphire-DisableLocationServices","ctt-WPFTweaksLocation"},"Restringir localização de aplicativos e sistema","Restrict app and system location");
        merge("raphire-DisableModernStandbyNetworking",new[]{"ctt-WPFToggleStandbyFix"},"Desativar rede durante a suspensão conectada","Disable connected-standby networking");
        var standby=result.Last().Variants[0];standby.Definition=Copy(standby.Definition,standby.Definition.Settings().Select(s=>new TweakSetting{Hive=s.Hive,Path=s.Path,Name=s.Name,Value=0,Kind=s.Kind}));
        var home=Preference(raw["raphire-DisableSettingsHome"]);home.Id="settings-home";home.Pt="Página inicial das Configurações";home.En="Settings home page";home.Category="interface";var showHome=Variant(Copy(raw["ctt-WPFToggleHideSettingsHome"],new[]{Page("HKCU","home",false),Page("HKLM","home",false)}),"Mostrar","Show");var hideHome=Variant(Copy(raw["raphire-DisableSettingsHome"],new[]{Page("HKCU","home",true),Page("HKLM","home",true)}),"Ocultar","Hide");home.Variants.Add(showHome);home.Variants.Add(hideHome);result.Add(home);used.Add(showHome.Definition.Id);used.Add(hideHome.Definition.Id);
        var ai=Preference(raw["ctt-WPFTweaksWindowsAI"]);ai.Pt="Ocultar página de componentes de IA nas Configurações";ai.En="Hide AI components page in Settings";var aiVariant=Variant(Copy(raw[ai.Id],new[]{Page("HKCU","aicomponents",true),Page("HKLM","aicomponents",true)}));ai.Variants.Add(aiVariant);result.Add(ai);used.Add(ai.Id);
        used.Add("ctt-WPFTweaksRemoveHomeAndGallery");
        foreach(var original in raw.Values.Where(x=>!used.Contains(x.Id))){var pref=Preference(original);var item=Variant(Copy(original,original.Settings()));if(original.Id=="raphire-HideHome"||original.Id=="raphire-HideGallery"||original.Id=="raphire-DisableNotepadAI")item.LegacyIds.Add(original.Id=="raphire-DisableNotepadAI"?"ctt-WPFTweaksWindowsAI":"ctt-WPFTweaksRemoveHomeAndGallery");if(original.Id=="ctt-WPFTweaksRazerBlock"){pref.Pt="Restringir coinstaladores de fabricantes";pref.En="Restrict manufacturer co-installers";}if(original.Id=="dism-0-2-0"){pref.Pt="Ocultar avisos de segurança na bandeja (legado)";pref.En="Hide legacy security tray alerts";item.Definition.MaxBuild=19045;}pref.Variants.Add(item);result.Add(pref);}
        result.First(x=>x.Id=="explorer-start").Variants.First(x=>x.Definition.Id=="raphire-ExplorerToThisPC").LegacyIds.Add("ctt-WPFTweaksRemoveHomeAndGallery");
        // Specific controls own their setting. Composite presets retain only their additional effects.
        var owners=new Dictionary<string,TweakPreference>(StringComparer.OrdinalIgnoreCase);var priority=new HashSet<string>(new[]{"start-recommendations","advertising","activity-history","edge-promotions","raphire-HideChat","raphire-DisableNotepadAI","raphire-DisableDriverUpdates"},StringComparer.OrdinalIgnoreCase);
        foreach(var pref in result.OrderBy(x=>x.Multiple?0:priority.Contains(x.Id)?1:2).ThenBy(x=>x.Multiple?0:x.Variants[0].Definition.Settings().Count())){foreach(var variant in pref.Variants){var original=variant.Definition;var retained=original.Settings().Where(s=>!owners.ContainsKey(TweakRegistryEngine.Identity(s))||owners[TweakRegistryEngine.Identity(s)]==pref).ToArray();foreach(var setting in retained)owners[TweakRegistryEngine.Identity(setting)]=pref;variant.Definition=Copy(original,retained);}pref.Variants.RemoveAll(x=>x.Definition==null);}
        result.RemoveAll(x=>x.Variants.Count==0);foreach(var pref in result)foreach(var variant in pref.Variants){variant.Definition.Pt=pref.Pt+(pref.Multiple?" • "+variant.Pt:"");variant.Definition.En=pref.En+(pref.Multiple?" • "+variant.En:"");}
        return result;
