    public static TweakVariant Current(TweakPreference pref,IRegistryStore store,int build){return pref.Variants.Where(x=>x.Definition.Supported(build)).OrderByDescending(x=>x.Definition.Settings().Count()).FirstOrDefault(x=>TweakRegistryEngine.State(x.Definition,store)==true);}
